FA='B Zar'; EN='Times New Roman'
LATIN=re.compile(r'(?:[A-Za-z][A-Za-z0-9_./@:+%()=\-]*)(?:[ \t]+[A-Za-z][A-Za-z0-9_./@:+%()=\-]*)*|\d+(?:\s*×\s*\d+)+')
DIACRITICS=re.compile('[\u064b-\u0652\u0670]')

def fmt(run,size=12,bold=False,latin=False):
    run.font.name=EN if latin else FA
    run.font.size=Pt(size-1 if latin else size)
    run.font.bold=bold
    run.font.color.rgb=RGBColor(0,0,0)
    pr=run._element.get_or_add_rPr()
    rf=pr.find(qn('w:rFonts'))
    for k in ['ascii','hAnsi','cs','eastAsia']:rf.set(qn('w:'+k),EN if latin else FA)
    for tag,val in [('szCs',str(int((size-1 if latin else size)*2))),('rtl','0' if latin else '1'),('lang','en-US' if latin else 'fa-IR')]:
        e=OxmlElement('w:'+tag)
        if tag=='lang':e.set(qn('w:val'),val);e.set(qn('w:bidi'),'fa-IR')
        else:e.set(qn('w:val'),val)
        pr.append(e)
    return run

def write(par,text,size=12,bold=False):
    text=DIACRITICS.sub('',text)
    pos=0
    for m in LATIN.finditer(text):
        if m.start()>pos:fmt(par.add_run(text[pos:m.start()]),size,bold)
        fmt(par.add_run(m.group()),size,bold,True)
        pos=m.end()
    if pos<len(text):fmt(par.add_run(text[pos:]),size,bold)

def bidi(par,rtl=True):
    e=OxmlElement('w:bidi');e.set(qn('w:val'),'1' if rtl else '0');par._p.get_or_add_pPr().append(e)

def p(doc,text='',bold=False):
    par=doc.add_paragraph();bidi(par);write(par,text,bold=bold)
    return par

def h(doc,text,level=1):
    par=doc.add_paragraph(style='Heading '+str(level));bidi(par)
    write(par,text,15 if level==1 else 13,bold=True)
    return par

def eq(doc,text):
    par=doc.add_paragraph();par.alignment=WD_ALIGN_PARAGRAPH.CENTER;bidi(par,False)
    om=OxmlElement('m:oMath')
    r=OxmlElement('m:r');rp=OxmlElement('m:rPr');sty=OxmlElement('m:sty');sty.set(qn('m:val'),'p');rp.append(sty);r.append(rp)
    wpr=OxmlElement('w:rPr');rf=OxmlElement('w:rFonts')
    for k in ['ascii','hAnsi','cs']:rf.set(qn('w:'+k),EN)
    wpr.append(rf)
    for tag in ['sz','szCs']:
        e=OxmlElement('w:'+tag);e.set(qn('w:val'),'22');wpr.append(e)
    e=OxmlElement('w:rtl');e.set(qn('w:val'),'0');wpr.append(e);r.append(wpr)
    def mr(value):
        rr=OxmlElement('m:r');rr.append(__import__('copy').deepcopy(rp));rr.append(__import__('copy').deepcopy(wpr))
        tt=OxmlElement('m:t');tt.text=value;rr.append(tt);return rr
    pos=0
    for match in re.finditer(r'([A-Za-z_]+)\^([0-9.]+)',text):
        if match.start()>pos:om.append(mr(text[pos:match.start()]))
        ss=OxmlElement('m:sSup');base=OxmlElement('m:e');base.append(mr(match.group(1)))
        sup=OxmlElement('m:sup');sup.append(mr(match.group(2)));ss.append(base);ss.append(sup);om.append(ss);pos=match.end()
    if pos<len(text):om.append(mr(text[pos:]))
    par._p.append(om)
    par.paragraph_format.space_before=Pt(3);par.paragraph_format.space_after=Pt(6)
    return par

def table(doc,headers,rows,widths=None):
    t=doc.add_table(rows=1,cols=len(headers));t.alignment=WD_TABLE_ALIGNMENT.CENTER;t.autofit=False
    pr=t._tbl.tblPr
    e=OxmlElement('w:bidiVisual');e.set(qn('w:val'),'1');pr.append(e)
    borders=OxmlElement('w:tblBorders')
    for side in ['top','left','bottom','right','insideH','insideV']:
        e=OxmlElement('w:'+side)
        for k,v in [('val','single'),('sz','4'),('color','D9D9D9')]:e.set(qn('w:'+k),v)
        borders.append(e)
    pr.append(borders)
    hdr=OxmlElement('w:tblHeader');t.rows[0]._tr.get_or_add_trPr().append(hdr)
    for idx,vals in enumerate([headers]+list(rows)):
        row=t.rows[0] if idx==0 else t.add_row()
        cant=OxmlElement('w:cantSplit');row._tr.get_or_add_trPr().append(cant)
        for j,(cell,text) in enumerate(zip(row.cells,vals)):
            if widths:cell.width=Cm(widths[j])
            cell.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
            cp=cell._tc.get_or_add_tcPr();mar=OxmlElement('w:tcMar')
            for k,v in [('top','75'),('bottom','75'),('start','90'),('end','90')]:
                e=OxmlElement('w:'+k);e.set(qn('w:w'),v);e.set(qn('w:type'),'dxa');mar.append(e)
            cp.append(mar)
            if idx==0:
                e=OxmlElement('w:shd');e.set(qn('w:fill'),'E4E7EB');cp.append(e)
            par=cell.paragraphs[0];bidi(par)
            par.alignment=WD_ALIGN_PARAGRAPH.CENTER
            par.paragraph_format.space_after=Pt(0);par.paragraph_format.line_spacing=1.1
            write(par,str(text),bold=idx==0)
    doc.add_paragraph().paragraph_format.space_after=Pt(1)
    return t

def picture(doc,path,width=16):
    par=doc.add_paragraph();par.alignment=WD_ALIGN_PARAGRAPH.CENTER
    par.add_run().add_picture(str(path),width=Cm(width))
    par.paragraph_format.keep_with_next=True

def link(doc,label,target):
    par=doc.add_paragraph();bidi(par)
    hyp=OxmlElement('w:hyperlink');hyp.set(qn('r:id'),doc.part.relate_to(target,RT.HYPERLINK,is_external=True))
    r=OxmlElement('w:r');rp=OxmlElement('w:rPr');rf=OxmlElement('w:rFonts')
    for k in ['ascii','hAnsi','cs']:rf.set(qn('w:'+k),FA)
    rp.append(rf)
    for tag,val in [('sz','24'),('szCs','24'),('rtl','1')]:
        e=OxmlElement('w:'+tag);e.set(qn('w:val'),val);rp.append(e)
    e=OxmlElement('w:color');e.set(qn('w:val'),'000000');rp.append(e)
    r.append(rp);tt=OxmlElement('w:t');tt.text=label;r.append(tt);hyp.append(r);par._p.append(hyp)

def newdoc(title,subtitle):
    d=Document();s=d.sections[0]
    s.page_width=Cm(21);s.page_height=Cm(29.7)
    s.top_margin=Cm(1.8);s.bottom_margin=Cm(1.8);s.left_margin=Cm(2);s.right_margin=Cm(2)
    s.header_distance=Cm(.8);s.footer_distance=Cm(.8)
    for name,size in [('Normal',12),('Title',19),('Heading 1',15),('Heading 2',13),('Footer',12)]:
        st=d.styles[name];st.font.name=FA;st.font.size=Pt(size);st.font.color.rgb=RGBColor(0,0,0)
        st._element.get_or_add_rPr().append(OxmlElement('w:rtl'))
        st.paragraph_format.line_spacing=1.2
        st.paragraph_format.space_after=Pt(5)
        st.paragraph_format.alignment=WD_ALIGN_PARAGRAPH.RIGHT
        if name.startswith('Heading'):
            st.paragraph_format.space_before=Pt(10);st.paragraph_format.keep_with_next=True
    for st in d.styles:
        for e in list(st._element.iter(qn('w:pBdr'))):e.getparent().remove(e)
    par=d.add_paragraph(style='Title');bidi(par);write(par,title,19,True)
    p(d,subtitle)
    fp=s.footer.paragraphs[0];fp.alignment=WD_ALIGN_PARAGRAPH.CENTER;bidi(fp)
    write(fp,'صفحه ')
    fld=OxmlElement('w:fldSimple');fld.set(qn('w:instr'),'PAGE');
    rr=OxmlElement('w:r');rp=OxmlElement('w:rPr');rf=OxmlElement('w:rFonts')
    for k in ['ascii','hAnsi','cs']:rf.set(qn('w:'+k),FA)
    rp.append(rf)
    for tag,val in [('sz','24'),('szCs','24'),('rtl','1')]:
        ee=OxmlElement('w:'+tag);ee.set(qn('w:val'),val);rp.append(ee)
    rr.append(rp);tt=OxmlElement('w:t');tt.text='۱';rr.append(tt);fld.append(rr);fp._p.append(fld)
    return d

def layers(doc,indices):
    rows=[]
    for i in indices:
        m=MODEL['layers'][i]
        shape=m['output']
        text=' × '.join(map(str,shape[1:])) if isinstance(shape,list) and shape and isinstance(shape[0],int) else 'سه مقیاس'
        rows.append([str(i),m['type'],text])
    table(doc,['شماره در کد','ماژول','کانال × ارتفاع × عرض'],rows,[2.5,4.5,10])

