    q('سهم اصلی کار خودت چه بوده است؟','آماده‌سازی و بررسی داده، بازتقسیم در سطح ویدیو، حذف موارد معیوب و تکراری، انتخاب پیکربندی آموزش و تحلیل نتایج.','معماری پایه و الگوریتم آموزش از Ultralytics هستند. ادعای طراحی یک معماری جدید ندارم؛ سهم پروژه، تطبیق و ارزیابی مستند مدل روی داده ترافیکی ایران است.')
    q('چرا YOLOv11s را انتخاب کردی؟','ساختار یک‌مرحله‌ای و مدل کوچک با حدود ۹٫۴ میلیون پارامتر، با مسئله و حافظه در دسترس سازگار بود.','s مقیاس مدل است. انتخاب آن یک تصمیم عملی با محدودیت سخت‌افزار بوده؛ برتری همه‌جانبه آن بر همه مدل‌ها ادعا نشده است.')
    q('چرا از YOLOv8 استفاده نکردی و آیا نسخه ۱۱ بهتر است؟','نسخه ۱۱ بلوک‌های C3k2، توجه C2PSA و شاخه طبقه‌بندی سبک‌تری دارد. در این پروژه انتخاب شد، اما آزمون مستقیم نسخه ۸ روی همین داده انجام ندادیم.','بنابراین می‌توان تفاوت ساختاری را توضیح داد؛ نمی‌توان عدد نتیجه نسخه ۱۱ را اثبات برتری تجربی بر نسخه ۸ در IADD دانست.')
    q('آموزش از صفر بوده یا تنظیم دقیق؟','تنظیم دقیق از وزن‌های از پیش آموزش‌دیده روی COCO.','شبکه از وزن‌های تصادفی آغاز نکرده است. در ران اصلی freeze تعیین نشده؛ لایه‌های ابتدایی نیز قابل تنظیم‌اند. یادگیری انتقالی به معنی آموزش‌ندادن قطعی همه لایه‌های ابتدایی نیست.')
    q('چرا IADD و نه داده آمریکایی؟','IADD صحنه‌های ترافیکی ایران را دارد و با هدف پروژه تناسب بیشتری داشت.','انتخاب داده بومی با هماهنگی استاد انجام شد. ضرورت مطلق استفاده از داده ایرانی یا اندازه‌گیری افت تغییر دامنه ادعا نشده است. مقاله معرفی IADD مرجع ۱ پایان‌نامه است.')
    group('۳  انتشار پیش‌رو و ماژول‌های شبکه')
    q('مسیر تصویر تا خروجی را خلاصه توضیح بده.','آماده‌سازی تصویر، استخراج ویژگی با پیچش و C3k2، پردازش زمینه با SPPF و توجه C2PSA، ادغام چندمقیاسی در گردن، تولید کادر و رده در سر، سپس غربال کادرها.','در استنتاج، برچسب مرجع وارد شبکه نمی‌شود و وزن‌ها تغییر نمی‌کنند. در آموزش پس از خروجی خام، تابع خطا و انتشار پس‌رو اضافه می‌شوند.')
    q('نگاشت ویژگی چیست و کانال چه معنایی دارد؟','نگاشت ویژگی، پاسخ یک فیلتر در مکان‌های مختلف است. کانال‌های عمیق، توصیف‌های آموخته‌شده‌اند و دیگر کانال رنگ قرمز و آبی نیستند.','سه کانال ورودی رنگ‌اند؛ ۵۱۲ کانال عمیق یعنی ۵۱۲ پاسخ ویژگی در هر موقعیت. نام‌گذاری قطعی یک کانال به عنوان چرخ یا شخص بدون تحلیل جداگانه درست نیست.')
    q('پیچش دقیقا چه محاسبه‌ای می‌کند؟','در یک همسایگی، مقدارهای ورودی را در وزن‌های فیلتر ضرب و جمع می‌کند و همین وزن‌ها را در همه موقعیت‌ها به کار می‌برد.','در لایه چندکانالی، مجموع روی کانال و دو بعد هسته انجام می‌شود. وزن‌ها با گرادیان آموخته می‌شوند. فرمول و مثال ۳×۳ در بخش دو راهنمای معماری آمده است.')
    q('پیچش ۱×۱ چه فایده‌ای دارد؟','کانال‌ها را در هر موقعیت ترکیب و تعداد آن‌ها را کم یا زیاد می‌کند.','به تنهایی همسایه‌های مکانی را بررسی نمی‌کند؛ برای فشرده‌سازی، گسترش و ادغام ویژگی‌های کانالی استفاده می‌شود.')
    q('گام و حاشیه‌گذاری چه هستند؟','گام فاصله حرکت هسته و حاشیه‌گذاری افزودن مقدار پیرامون ورودی است.','با هسته ۳، حاشیه یک و گام دو، بعد زوج نصف می‌شود. حاشیه صفر داخل پیچش با حاشیه رنگ ۱۱۴ آماده‌سازی تصویر متفاوت است.')
    q('میدان دریافت با گام خروجی یکی است؟','خیر. گام فاصله موقعیت‌های نگاشت در مختصات تصویر است؛ میدان دریافت ناحیه‌ای از ورودی است که بر یک پاسخ اثر می‌گذارد.','در اثر چند لایه، میدان دریافت بزرگ‌تر می‌شود. وجود توجه نیز می‌تواند وابستگی به موقعیت‌های دور را اضافه کند.')
    q('چرا هم نرمال‌سازی و هم SiLU لازم‌اند؟','نرمال‌سازی مقیاس پاسخ‌ها را تنظیم می‌کند؛ SiLU رابطه غیرخطی وارد شبکه می‌کند.','در آموزش آمار دسته و در ارزیابی آمار انباشته‌شده نرمال‌سازی به کار می‌روند. فقط γ و β آموختنی‌اند. فرمول SiLU برابر z×sigmoid(z) است.')
    q('C3k2 چه می‌کند و عدد دو یعنی فیلتر ۲×۲؟','ویژگی را در مسیر مستقیم و مسیر پردازش‌شده عبور می‌دهد و سپس خروجی‌ها را ادغام می‌کند. عدد دو به معنی هسته ۲×۲ نیست.','در اولین بلوک واقعی، کانال‌ها ۶۴→دو شاخه ۳۲→سه خروجی ۳۲→۹۶→۱۲۸ می‌شوند. در بلوک‌های عمیق با c3k=True مسیر داخلی C3k داریم.')
    q('اتصال باقیمانده چه کمکی می‌کند؟','خروجی یک تبدیل را به ورودی سازگار آن اضافه می‌کند و مسیری مستقیم برای اطلاعات و گرادیان فراهم می‌آورد.','جمع با Concat فرق دارد. در بعضی Bottleneckها به علت ناسازگاری کانال یا تنظیم بلوک، اتصال جمع فعال نیست؛ نباید همه ماژول‌ها را یکسان توصیف کرد.')
    q('SPPF چه می‌کند و خودش فیلتر آموختنی دارد؟','با سه بیشینه‌گیری پیاپی ۵×۵، زمینه را در چند محدوده ترکیب می‌کند. خود بیشینه‌گیری وزن ندارد؛ پیچش‌های ابتدا و انتهای بلوک وزن دارند.','محدوده موثر بیشینه‌گیری‌ها روی نگاشت ۵، ۹ و ۱۳ است. تفکیک مکانی ثابت می‌ماند. این بلوک در YOLOv8 هم وجود دارد.')
    q('C2PSA چیست و چرا فقط بخشی از کانال‌ها توجه دارند؟','بخشی از ویژگی‌ها از توجه مکانی و شبکه پیش‌خور عبور می‌کنند و بخش دیگر مسیر مستقیم دارد.','در مدل s پروژه، شاخه توجه ۲۵۶ کانال و چهار سر دارد و روی نگاشت ۴۰×۴۰ مثال مربعی کار می‌کند. پردازش جزئی، هزینه توجه را نسبت به اجرای آن روی تمام کانال‌ها کاهش می‌دهد.')
    q('Q و K و V را ساده توضیح بده.','Q درخواست اطلاعات یک موقعیت، K مشخصات قابل تطبیق موقعیت‌ها و V محتوایی است که با وزن توجه ترکیب می‌شود.','این‌ها سه تصویر جدا یا برچسب واقعی نیستند؛ تبدیل‌های آموختنی از ویژگی‌اند. شباهت Q و K بعد از مقیاس‌دهی و softmax، وزن ترکیب V را می‌سازد.')
    q('SPPF و C2PSA در backbone هستند یا neck؟','در پیکربندی رسمی، انتهای backbone و قبل از نخستین بزرگ‌نمایی قرار دارند؛ در شکل پایان‌نامه در مرز گردن نمایش داده شده‌اند.','ملاک توضیح مسیر اجرا، ترتیب ماژول‌ها و اتصال‌های واقعی است. مرزبندی مفهومی شکل نباید به جابه‌جایی عملیات در کد تعبیر شود.')
    q('چرا شبکه سه مقیاس خروجی دارد؟','برای استفاده هم‌زمان از ویژگی‌های دارای تفکیک زیاد و ویژگی‌های عمیق‌تر با زمینه بزرگ‌تر.','ورودی مربعی ۱۲۸۰ به نگاشت‌های ۱۶۰،۸۰،۴۰ در سر می‌رسد. این‌ها نقش نسبی در اندازه اشیا دارند و به سه بازه قطعی اندازه جدول داده محدود نیستند.')
    q('Upsample اطلاعات حذف‌شده تصویر را برمی‌گرداند؟','خیر. در این مدل نزدیک‌ترین همسایه مقادیر ویژگی را تکرار می‌کند تا ابعاد برای ادغام سازگار شوند.','جزئیات مکانی از اتصال ویژگی‌های ذخیره‌شده کم‌عمق می‌آید، نه از ساخت پیکسل تازه به وسیله بزرگ‌نمایی.')
    q('Concat با جمع چه فرقی دارد؟','Concat کانال‌ها را کنار هم قرار می‌دهد؛ جمع، مقدارهای متناظر را به هم اضافه می‌کند.','مثلا در مرحله دوازده ۵۱۲+۲۵۶=۷۶۸ کانال داریم. در جمع باقیمانده تعداد کانال به این شکل افزایش پیدا نمی‌کند. هر دو عمل پارامتر مستقلی ندارند.')
    q('خروجی خام سر چند مقدار دارد؟','در هر موقعیت ۷۰ مقدار خام: ۶۴ برای توزیع چهار فاصله و شش برای رده. پس از بازسازی کادر، چهار مقدار مکان و شش امتیاز باقی می‌ماند.','برای تصویر مربعی ۳۳٬۶۰۰ موقعیت داریم. خروجی پیش از NMS شکل 1 × 10 × 33600 دارد. این موقعیت‌ها تعداد اشیای نهایی نیستند.')
    q('بدون لنگر یعنی شبکه هیچ نقطه مرجعی ندارد؟','خیر. نقطه‌های مرجع شبکه وجود دارند؛ کادر لنگر با اندازه و نسبت از پیش تعیین‌شده نداریم.','اسم anchor_points در کد به نقطه مرجع اشاره دارد. شبکه فاصله چهار طرف کادر را نسبت به آن پیش‌بینی می‌کند.')
    q('DFL چیست و reg_max=16 یعنی چه؟','برای هر فاصله چهارطرفه کادر، توزیعی روی ۱۶ بازه می‌سازیم و فاصله پیوسته را از میانگین وزنی آن می‌گیریم.','۱۶ نه تعداد رده است، نه حد تعداد اشیا و نه ۱۶ پیکسل. فاصله سلولی در گام هر مقیاس ضرب می‌شود. هدف غیرصحیح مانند ۷٫۶ از دو بازه مجاور در آموزش استفاده می‌کند.')
    q('برای رده‌ها softmax استفاده شده است؟','در سر این مدل برای هر رده sigmoid داریم. softmax روی بازه‌های فاصله DFL و در توجه به کار می‌رود.','بنابراین مجموع امتیاز شش رده لازم نیست یک باشد. نسخه‌های قدیمی و مدل‌های طبقه‌بندی تصویر را نباید با سر فعلی یکی دانست.')
    q('آیا خروجی مستقل objectness یا رده پس‌زمینه داریم؟','در سر YOLOv11s پروژه خروجی مستقل objectness نداریم؛ شش امتیاز رده داریم. پس‌زمینه در ماتریس، نقش حساب‌کردن خطاها را دارد.','ردیف یا ستون پس‌زمینه به معنی آموزش رده هفتم نیست. نامزدهای نامناسب از طریق هدف‌های طبقه‌بندی و غربال پیش‌بینی‌ها کنترل می‌شوند.')
    q('فیلتر عمقی چیست و کجا به کار رفته؟','در پیچش عمقی هر کانال جداگانه پردازش می‌شود؛ پیچش ۱×۱ پس از آن کانال‌ها را ترکیب می‌کند.','در شاخه رده سر و جزء مکانی توجه وجود دارد. این تقسیم محاسبه می‌تواند هزینه را کمتر کند؛ همه پیچش‌های شبکه عمقی نیستند.')
    group('۴  آموزش خطا و به‌روزرسانی وزن‌ها')
    q('سه خطای آموزش چه هستند؟','box_loss برای مکان کادر با CIoU، cls_loss برای رده با BCE و dfl_loss برای توزیع فاصله‌ها.','ضریب‌ها ۷٫۵، ۰٫۵ و ۱٫۵ هستند. کد نرمال‌سازی و وزن‌دهی هدف نیز دارد؛ mAP و F1 تابع خطای مورد استفاده برای مشتق‌گیری نیستند.')
    q('CIoU با IoU چه فرقی دارد؟','IoU فقط نسبت مساحت اشتراک به اجتماع است؛ CIoU علاوه بر آن فاصله مرکز و نسبت ابعاد را هم در خطا لحاظ می‌کند.','این تفاوت باعث می‌شود کیفیت مکان‌یابی فقط به میزان اشتراک محدود نباشد. آستانه mAP هنوز با IoU معمول توضیح داده می‌شود.')
    q('چگونه هر کادر مرجع به خروجی شبکه مرتبط می‌شود؟','با انتساب سازگار با وظیفه که کیفیت رده و مکان را ترکیب می‌کند و نامزدهای مناسب را انتخاب می‌کند.','در نسخه پروژه، تا ده نامزد برای هر هدف بررسی می‌شود. یک شیء لزوما فقط یک سلول مثبت ندارد. هدف نرم و حل تعارض بخشی از پیاده‌سازی است.')
    q('forward و backward و optimizer.step چه تفاوتی دارند؟','forward پیش‌بینی و سپس خطا را می‌سازد؛ backward مشتق خطا نسبت به وزن‌ها را محاسبه می‌کند؛ optimizer.step وزن‌ها را تغییر می‌دهد.','در استنتاج تنها مسیر پیش‌رو و پردازش خروجی اجرا می‌شود. آموزش به برچسب مرجع نیاز دارد؛ استنتاج عادی ندارد.')
    q('گرادیان و قاعده زنجیره‌ای را با یک مثال توضیح بده.','اگر y=wx و خطا نصف مربع y−t باشد، مشتق وزن (wx−t)x است. علامت و اندازه آن مسیر به‌روزرسانی را تعیین می‌کند.','با w=0.2، x=0.8 و t=1، گرادیان ۰٫۶۷۲− می‌شود. SGD با نرخ ۰٫۰۱ وزن را به ۰٫۲۰۶۷۲ می‌رساند. این مثال آموزشی است، نه وزن واقعی شبکه.')
    q('گرادیان از گردن و توجه چگونه عبور می‌کند؟','از همان اتصال‌های گراف محاسبه: در Concat بخش‌بندی، در جمع توزیع به دو مسیر و در توجه مشتق تبدیل‌ها و وزن‌های توجه.','در فیلتر مشترک، سهم مکان‌ها جمع می‌شود. بیشینه‌گیری سهم را به محل بیشینه می‌فرستد. این موضوع را با نمودار مسیر شبکه و قاعده زنجیره‌ای توضیح بده.')
    q('چرا گرادیان باید صفر شود و انباشت چیست؟','گرادیان‌ها در حافظه جمع می‌شوند. بعد از گام بهینه‌ساز صفر می‌شوند؛ در انباشت، عمدا سهم چند دسته قبل از تغییر وزن جمع می‌شود.','در پروژه پس از گرم‌کردن حدود پنج دسته برای یک گام معمول است. اندازه دسته موثر حدود ۶۰ است و با دسته فیزیکی ۱۲ یکسان نیست؛ انتهای دوره و گرم‌کردن جزئیات دیگری دارند.')
    q('AdamW با SGD چه فرقی دارد؟','SGD از گرادیان و احتمالا تکانه استفاده می‌کند؛ AdamW حافظه گرادیان و مربع آن را برای مقیاس‌دهی تطبیقی نگه می‌دارد و کاهش وزن را جدا اعمال می‌کند.','در ران اصلی AdamW و در مرحله جداگانه ده‌دوره‌ای SGD بوده است. بهبود آزمایش، مربوط به بسته بهینه‌ساز و نرخ و زمان‌بند است؛ اثر خالص یک جزء جدا نشده است.')
    q('نرخ یادگیری آخر آموزش چقدر بوده و چرا ۰٫۰۰۰۰۱ نشده؟','در last.pt اصلی حدود ۰٫۰۰۰۶۴۸ است. کران ۰٫۰۰۰۰۱ برای پایان برنامه ۱۵۰ دوره‌ای بود، اما اجرا بعد از ۶۲ دوره تمام شد.','زمان‌بند بر پایه تعداد دوره برنامه‌ریزی‌شده عمل می‌کند. برنامه با زمان‌بند کسینوسی بوده؛ مرحله جداگانه ده‌دوره‌ای نرخ اولیه و زمان‌بند دیگری دارد.')
    q('warmup و weight decay و AMP چه می‌کنند؟','گرم‌کردن، شروع تدریجی آموزش را تنظیم می‌کند؛ کاهش وزن بزرگی وزن‌ها را کنترل می‌کند؛ دقت ترکیبی مصرف محاسبه و حافظه را بهبود می‌دهد.','گرم‌کردن اصلی سه دوره است. کاهش وزن تنظیم‌شده ۰٫۰۰۰۵ و مقدار موثر ذخیره‌شده گروه وزن‌ها ۰٫۰۰۰۴۶۸۷۵ است؛ بایاس و نرمال‌سازی کاهش وزن صفر دارند. AMP با مقیاس‌دهی گرادیان همراه است.')
    q('بهترین وزن با آخرین وزن چه فرقی دارد؟','best.pt بهترین وضعیت اعتبارسنجی را نگه می‌دارد؛ last.pt آخرین وضعیت اجرا و اطلاعات لازم برای ادامه را دارد.','مدل نهایی بهترین دوره ۵۱ است، نه آخرین دوره ۶۲. وضعیت آخر شامل شمارنده بهینه‌ساز و اطلاعات ادامه آموزش بوده است.')
    q('برازش داخلی و سلول بررسی همگرایی یکی هستند؟','در نسخه ثبت‌شده وزن پروژه، برازش داخلی برابر mAP@0.5:0.95 بوده است. سلول کمکی دفترچه ترکیب ۰٫۱ و ۰٫۹ دو معیار را برای بررسی چاپ می‌کند.','شواهد فایل وزن: best_fitness=0.68725 و mAP@0.5:0.95 همان مقدار دارد. تعریف نسخه‌های دیگر کتابخانه را نباید بدون بررسی به این اجرا نسبت داد.')
    q('چرا آموزش اصلی ۱۵۰ دوره اجرا نشد؟','۱۵۰ سقف برنامه بود؛ ۶۲ دوره ثبت شده است و بهترین برازش به دوره ۵۱ مربوط است. تنظیم patience=10 برای توقف در نبود پیشرفت داشتیم.','شماره دوره داخل وزن از صفر است؛ epoch=50 یعنی دوره ۵۱. گزارش پایان‌نامه، توقف زودهنگام و سپس مرحله جداگانه ده‌دوره‌ای را توضیح می‌دهد.')
    q('در ده دوره تکمیلی دقیقا چه اتفاقی افتاد؟','از بهترین وزن اصلی شروع شد؛ موزاییک و ترکیب وزنی صفر و بهینه‌ساز SGD بود. نتیجه اعتبارسنجی بهتر نشد و وزن اصلی انتخاب نهایی ماند.','این مرحله را ادامه بدون تغییر AdamW ننام. با اجرای ۶۲ دوره از برنامه ۱۵۰، close_mosaic=10 در اصلی به تنهایی خاموشی ده دوره انتهایی واقعی را تضمین نکرده است؛ خاموشی تکمیلی صریح بوده است.')
    q('آیا AdamW را به طور قطعی بهتر از SGD ثابت کردی؟','برای پیکربندی پروژه، راهبرد دوم نتیجه اعتبارسنجی بهتری داشت و انتخاب شد.','بهینه‌ساز، نرخ اولیه و زمان‌بند هم‌زمان تغییر کرده‌اند؛ بنابراین نتیجه، مقایسه دو راهبرد است. برای حکم عمومی باید اجزا جدا و با چند بذر تصادفی آزمایش شوند.')
    group('۵  داده و ساخت زیرمجموعه نهایی')
    q('چرا بخش test اصلی IADD استفاده نشد؟','۱۴٬۴۸۶ تصویر آزمون قابل دریافت برچسب عمومی نداشتند؛ برای آموزش و ارزیابی قابل محاسبه، از تصاویر برچسب‌دار train و val استفاده کردیم.','برچسب‌گذاری مجدد انجام نداده‌ایم. تصاویر برچسب‌دار تجمیع و در سطح ویدیو به سه بخش جدید تقسیم شدند. این یک تفاوت با آزمایش مقاله اصلی است.')
    q('نشت داده چه بود و چگونه رفع شد؟','فریم‌های یک ویدیو در بخش‌های اصلی پراکنده بودند و به علت شباهت، ارزیابی می‌توانست بیش از حد خوش‌بینانه شود. در تقسیم جدید هر ویدیو فقط در یک بخش است.','اشتراک نام ویدیو و تصویر در سه بخش برنامه‌نویسی‌شده بررسی شده است. صفرشدن اشتراک ویدیو جلوی همان مسیر نشت را می‌گیرد؛ اثبات استقلال از هر نظر ممکن نیست.')
    q('چرا حذف فایل تکراری تصویر کافی نبود؟','دو ویدیو با شناسه متفاوت می‌توانند صحنه‌های تکراری داشته باشند؛ پس اشتراک نام صفر هم لزوما همه تکرارها را حذف نمی‌کند.','در پروژه یک عضو از هر سه جفت ویدیوی تکراری کنار گذاشته شد. تشخیص با شواهد شباهت و بازبینی انجام شده و کد و تصاویر آن در مدارک مکمل موجودند.')
    q('چه ویدیوهایی حذف شدند؟','دو مورد برچسب معیوب Record426_D و Record046_D و سه نسخه تکراری Record407_D و Record416_R و Record043_D.','هر حذف باید به شواهد همان مورد وصل شود. پایین‌بودن نتیجه مدل به تنهایی دلیل حذف یک ویدیو نیست. آستانه غربال برای پیدا کردن نامزد بررسی بوده، نه حکم خودکار خرابی.')
    q('چرا زیرمجموعه ساختی و همه تصاویر را نگه نداشتی؟','به دلیل هزینه آموزش و محدودیت محیط، حجم قابل مدیریت ساخته شد؛ ضمن اینکه تقسیم ویدیویی و حفظ رده‌های کم‌نمونه رعایت شد.','مجموع نهایی ۳۷٬۱۴۲ تصویر از ۱۶۰ ویدیو است. کوچک‌ترکردن مجموعه فقط کم‌کردن تصادفی همه فریم‌ها نیست؛ سیاست حفظ فریم‌های دارای رده‌های منتخب نیز وجود دارد.')
    q('نسبت ۷۰ و ۱۵ و ۱۵ درصد بر حسب چیست؟','تعداد تصویر؛ ویدیو واحد مستقل تقسیم است.','آموزش ۲۶٬۰۰۰ تصویر و ۷۹ ویدیو، اعتبارسنجی ۵٬۵۷۱ و ۳۹، آزمون ۵٬۵۷۱ و ۴۲ دارد. درصد ویدیوها حدود ۴۹٫۴،۲۴٫۴،۲۶٫۳ است و نباید آن را با سهم تصاویر یکی گرفت.')
    q('کد تقسیم چگونه رده‌های کم‌نمونه را لحاظ می‌کند؟','در هر گروه شرایط، ویدیوها با توجه به تعداد نمونه رده‌های منتخب و اندازه ویدیو مرتب و به بخش دارای کسری نسبت به هدف تخصیص داده می‌شوند.','رده‌های منتخب با شناسه‌های ۲،۳،۵ یعنی موتورسیکلت، اتوبوس و چراغ راهنمایی‌اند. در ساخت زیرمجموعه فریم‌های دارای این‌ها نگه داشته و از فریم‌های دیگر تا حجم هدف انتخاب می‌شود. این وزن‌دهی تابع خطا یا تولید برچسب تازه نیست.')
    q('هم‌ترازی دشواری یعنی چه و آیا دقیقا برابر است؟','توزیع اندازه اشیا، رده‌ها و شرایط محیطی در اعتبارسنجی و آزمون مقایسه شد تا تفاوت آشکار دشواری کمتر باشد.','هم‌ترازی، یکسانی کامل صحنه و دشواری هر تصویر نیست. کد تقسیم مستقیما روی شرایط و رده‌های کم‌نمونه کار می‌کند؛ اندازه اشیا در گزارش بررسی می‌شود. ادعا نکن کد همه سه محور را با یک تابع هدف ریاضی مشترک دقیقا بهینه کرده است.')
    q('اندازه کوچک و متوسط و بزرگ را چگونه تعریف کردی؟','بر پایه مساحت نسبی کادر: کمتر از ۰٫۰۱ کوچک، از ۰٫۰۱ تا کمتر از ۰٫۰۶ متوسط و از ۰٫۰۶ به بالا بزرگ.','مساحت نسبی برابر عرض نسبی ضرب در ارتفاع نسبی است. این آستانه‌ها تعریف تحلیل پروژه‌اند و با تعریف اندازه پیکسلی COCO یا گام سه شاخه سر یکسان نیستند.')
    q('شرایط روز و شب و باران و ابری از کجا آمده‌اند؟','از پسوند نام ویدیوها؛ D و N و R و A. درصدها با شمارش فایل تصویر در این گروه‌ها محاسبه شده‌اند.','نام‌گذاری A به عنوان ابری با بازبینی تصاویر تفسیر شده است؛ مقاله را منبع تعریف قطعی این کد معرفی نکن. شمارش همه تصاویر به صورت چشمی انجام نشده است.')
    q('سهم کلی شرایط و تعداد تصاویر چقدر است؟','روز ۳۰٬۰۶۷، شب ۳٬۲۸۵، باران ۳٬۲۷۶ و ابری ۵۱۴ تصویر؛ از مجموع ۳۷٬۱۴۲.','درصدها به ترتیب حدود ۸۱٫۰،۸٫۸،۸٫۸ و ۱٫۴ هستند. تعدادهای روز هر بخش ۲۱٬۴۱۶،۴٬۶۵۶،۳٬۹۹۵ در stats.json ثبت شده است. یک تصویر چند شیء دارد، اما فقط یک شرایط ویدیو دارد.','stats.json و شمارش پسوند شناسه ویدیو')
    q('شمار نمونه و نمونه در تصویر چگونه محاسبه شد؟','هر سطر معتبر برچسب یک شیء است. مجموع سطرها تعداد نمونه و تقسیم آن بر تعداد تصاویر، میانگین نمونه در تصویر است.','آموزش ۲۰۴٬۰۰۹، اعتبارسنجی ۳۶٬۸۱۰ و آزمون ۳۴٬۹۹۴ نمونه دارند؛ مجموع ۲۷۵٬۸۱۳. نمودار سهم رده، تعداد اشیاست؛ نمودار شرایط محیطی تعداد تصویر است.')
    q('عدم توازن را کاملا حل کردی؟','خیر؛ رده خودروی سبک غالب مانده است. سیاست حفظ فریم‌های رده‌های کم‌نمونه برای تشدیدنشدن عدم توازن استفاده شد.','معیارها به تفکیک رده گزارش شده‌اند. برابرکردن تعداد نمونه همه رده‌ها انجام نشده و در ران اصلی وزن‌دهی اختصاصی رده‌ها ادعا نمی‌شود.')
    group('۶  افزایش داده و تنظیمات')
    q('موزاییک و ترکیب وزنی چه تفاوتی دارند؟','موزاییک چند تصویر را در قاب ترکیبی کنار هم می‌گذارد؛ ترکیب وزنی دو تصویر را با وزن‌های مکمل روی هم می‌نشاند.','در تشخیص اشیا، کادرهای هر دو تصویر ترکیب وزنی نگه داشته می‌شوند. mixup=0.1 احتمال اعمال است، نه اینکه یک تصویر همیشه با وزن ۰٫۱ مخلوط شود.')
    q('ضریب روشنایی ۰٫۴ فقط شب را روشن‌تر می‌کند؟','خیر؛ تغییر تصادفی روشنایی در آموزش ایجاد می‌کند و می‌تواند روشن یا تیره کند.','این مقدار با پیش‌فرض کتابخانه برابر و در کد هم صریح آمده است. بر تصاویر آزمون برای کمک به مدل اعمال نشده است. احتمال بهبود تعمیم هدف آن است؛ اثر مستقل آن در پروژه اندازه‌گیری نشده است.')
    q('چرا ورودی ۱۲۸۰ انتخاب شد و بالاتر بهتر نبود؟','در مقایسه اجراهای پیشین، نتیجه بهتر و هزینه حافظه قابل مدیریت بود؛ زیرمجموعه نیز سقف ضلع ۱۲۸۰ دارد.','بزرگ‌کردن فایل‌های فعلی جزئیات از دست‌رفته را برنمی‌گرداند. استفاده از تصویر خام بزرگ‌تر آزمایش دیگری می‌خواهد. تغییر دسته ۱۶ به ۱۲ در مقایسه اندازه، مانع انتساب کاملا خالص اثر به اندازه تصویر است.')
    q('کدام تنظیمات اصلی را باید حفظ کنم؟','مدل s، اندازه ۱۲۸۰، دسته ۱۲، AdamW، نرخ ۰٫۰۰۱، کسینوسی، سقف ۱۵۰، patience=10، mixup=0.1 و degrees=5.','شش رده، بذر آموزش صفر و بذر ساخت داده ۸۰ را نیز جدا به خاطر بسپار. hsv_v=0.4 با پیش‌فرض برابر است. فایل args.yaml گزارش تنظیمات است، نه مدرک مستقل نتیجه یا شمار گام‌ها.')
    q('در هر دوره دقیقا همان تصویر دیده می‌شود؟','فایل‌ها همان مجموعه‌اند، اما ترتیب و تبدیل‌های تصادفی آموزش می‌توانند شکل ورودی را عوض کنند.','در اعتبارسنجی و آزمون افزایش داده تصادفی آموزش برای ارزیابی استاندارد اعمال نمی‌شود. نمونه‌های موزاییک ممکن است از چند فایل تشکیل شوند، پس تعداد فایل با تعداد محتوای دیده‌شده برابر نیست.')
    group('۷  معیارها آستانه‌ها و ماتریس')
    q('چرا accuracy گزارش نکردی؟','accuracy ساده طبقه‌بندی تصویر، معیار اصلی این آشکارساز نیست؛ معیارهای precision، recall و mAP برای رده و مکان کادر گزارش شده‌اند.','precision فقط مخصوص تشخیص اشیا نیست و در طبقه‌بندی هم کاربرد دارد. مشکل تعریف accuracy ساده در آشکارسازی، به‌ویژه شمارش همه منفی‌های واقعی زمینه است. پاسخ را به صورت «accuracy وجود ندارد» بیان نکن.')
    q('TP و FP و FN در پروژه چه هستند؟','TP پیش‌بینی با رده درست و کادر منطبق بر مرجع، FP پیش‌بینی پذیرفته‌شده بدون تطبیق درست و FN شیء مرجعی است که پیدا نشده است.','تطبیق با آستانه IoU مشخص انجام می‌شود و یک مرجع نمی‌تواند برای چند پیش‌بینی مستقل موفق شمرده شود. نبود برچسب شیء واقعی می‌تواند یک پیش‌بینی درست بصری را FP ارزیابی کند.')
    q('precision و recall و F1 را توضیح بده.','precision برابر TP/(TP+FP)، recall برابر TP/(TP+FN) و F1 برابر 2PR/(P+R) است.','اگر از ده کادر پذیرفته‌شده هشت درست باشند و ده شیء مرجع وجود داشته باشد، P و R هر دو ۰٫۸ می‌شوند. بالا‌بردن confidence معمولا کادرهای کمتر و موازنه متفاوت ایجاد می‌کند؛ رابطه معکوس جبری قطعی برای هر تغییر مدل وجود ندارد.')
    q('IoU را با یک مثال محاسبه کن.','مساحت اشتراک دو کادر تقسیم بر مساحت اجتماع آن‌هاست.','اگر دو کادر هر کدام ۱۰۰ واحد مساحت و اشتراک ۶۰ داشته باشند، اجتماع ۱۴۰ و IoU حدود ۰٫۴۲۹ است. یک کادر با برچسب درست اما مکان ضعیف می‌تواند ناموفق محسوب شود.')
    q('AP و mAP چه هستند و عدد ۰٫۵ چه معنایی دارد؟','AP خلاصه منحنی دقت و فراخوانی یک رده است؛ mAP میانگین AP رده‌هاست. در mAP@0.5، مقدار ۰٫۵ آستانه هم‌پوشانی با کادر مرجع است، نه confidence.','در mAP@0.5:0.95، مقادیر ده آستانه ۰٫۵،۰٫۵۵ تا۰٫۹۵ میانگین می‌شوند. سخت‌گیرانه‌تر است و مکان‌یابی دقیق‌تر را بیشتر می‌سنجد.')
    q('چرا گفتن mAP مستقل از confidence نیاز به دقت دارد؟','mAP منحنی حاصل از رتبه‌بندی امتیازها و موازنه آستانه‌های مختلف را خلاصه می‌کند؛ به یک نقطه confidence ثابت محدود نیست.','اما فیلتر شدید پیش‌بینی‌ها قبل از ارزیابی، NMS و جزئیات محاسبه می‌توانند آن را عوض کنند. پس استقلال مطلق از هر تنظیم اطمینان یا پردازش را ادعا نکن.')
    q('آستانه ۰٫۴۰۶ از کجا آمده و ۰٫۲۵ در کد چیست؟','۰٫۴۰۶ برای ماتریس از بیشینه میانگین F1 منحنی اعتبارسنجی گرفته شد. ۰٫۲۵ مقدار اولیه متغیر پیش از خواندن منحنی است.','مقادیر منحنی در mv.curves_results خوانده می‌شوند. بیشینه بخش آزمون برای تنظیم آستانه استفاده نشده است. mAP از ارزیابی اولیه با منحنی‌ها گزارش شده، نه صرفا از ماتریس این نقطه.')
    q('۰٫۷ و ۰٫۵ و ۰٫۴۰۶ را با هم مقایسه کن.','۰٫۷ آستانه هم‌پوشانی NMS، ۰٫۵ آستانه هم‌پوشانی معیار mAP@0.5 و ۰٫۴۰۶ آستانه امتیاز پذیرفتن پیش‌بینی برای ماتریس است.','ماتریس کتابخانه آستانه تطبیق جداگانه دارد که پیش‌فرض آن در نسخه بررسی‌شده ۰٫۴۵ است. پس هیچ‌کدام از این عددها را به جای دیگری استفاده نکن.','args.yaml، سلول ارزیابی و ConfusionMatrix.process_batch در metrics.py')
    q('پس‌زمینه در ماتریس چه معنایی دارد؟','یک رده واقعی شبکه نیست؛ خانه‌های آن پیش‌بینی بدون مرجع متناظر یا مرجع بدون پیش‌بینی متناظر را ثبت می‌کنند.','برای خواندن، ابتدا برچسب محورهای واقعی و پیش‌بینی‌شده شکل را ببین. عبارتی مانند «پس‌زمینه به خودرو تبدیل شده» یعنی کادری از خودرو بدون تطبیق با مرجع ثبت شده؛ ممکن است خطای مدل یا برچسب جاافتاده باشد. برای هر کادر باید تصویر بررسی شود.')
    q('چرا بعضی کادرهای ظاهرا درست خطا شمرده می‌شوند؟','ممکن است شیء برچسب نداشته باشد، رده پیش‌بینی متفاوت باشد، هم‌پوشانی کافی نباشد یا کادر تکراری برای همان شیء تولید شده باشد.','نمی‌توان از یک نمونه کیفی نتیجه گرفت همه FPها از نقص داده‌اند. مثال‌های بصری برای تشخیص نوع خطا کمک می‌کنند؛ ارزیابی کمی همچنان طبق مرجع انجام می‌شود.')
    q('آیا همه شش رده به اندازه تعدادشان در mAP تاثیر دارند؟','در میانگین رده‌ها، AP هر رده وزن برابر دارد.','رده با هزار نمونه و رده با ده‌هزار نمونه سهم مساوی در میانگین شش‌رده‌ای دارند، اما عدم قطعیت و میزان نمایندگی داده آن‌ها یکسان نیست.')
    group('۸  نتایج و خواندن نمودارها')
    q('نتیجه نهایی پروژه چه بود؟','روی آزمون، mAP@0.5 حدود ۰٫۸۷۴ و mAP@0.5:0.95 حدود ۰٫۷۰۷ است.','عدد اول به معنی ۸۷٫۴ درصد همه پیکسل‌ها یا همه تصاویر درست نیست. نتیجه مربوط به شش رده و تقسیم نهایی پروژه است، نه بخش آزمون اصلی IADD.','جدول نتایج پایان‌نامه و perclass_metrics.csv')
    q('چرا نتیجه آزمون از اعتبارسنجی بیشتر است؟','بخش‌های مستقل توزیع کاملا یکسان ندارند؛ اختلاف حدود ۲٫۵ واحد درصد در mAP@0.5 می‌تواند با نمونه‌ها و دشواری متفاوت مرتبط باشد.','به خودی خود مدرک نشت نیست. جدایی ویدیویی و آمار توزیع بررسی شده‌اند. بدون آزمایش بیشتر، علت دقیق همه اختلاف را به یک عامل نسبت نمی‌دهیم.')
    q('کدام رده بهتر و کدام دشوارتر بود؟','خودروی سبک AP@0.5 حدود ۰٫۹۶۹ دارد. اتوبوس حدود ۰٫۷۹۸ و چراغ راهنمایی حدود ۰٫۸۱۳ بوده‌اند.','برای توضیح دشواری باید اندازه، شباهت ظاهری، تعداد و کیفیت برچسب را با هم دید. اتوبوس فراخوانی پایین‌تری دارد؛ رده موتورسیکلت با AP@0.5 خوب، در معیار سخت‌گیرانه افت بیشتری دارد.','جدول رده‌ها در فصل سوم')
    q('افت زیاد معیار سخت‌گیرانه برای موتورسیکلت چه می‌گوید؟','تشخیص حضور و رده می‌تواند خوب باشد، اما مکان‌یابی در آستانه‌های سخت‌تر دشوارتر شود.','AP@0.5 موتورسیکلت حدود ۰٫۹۲۸ و AP در بازه آستانه‌ها حدود ۰٫۶۳۱ است. اندازه، پوشیدگی و کیفیت کادرها می‌توانند اثر داشته باشند؛ از این اختلاف به تنهایی علت قطعی استخراج نمی‌شود.')
    q('در نمودار آموزش چه چیزی را بررسی می‌کنی؟','روند خطای آموزش و اعتبارسنجی، رشد mAP، رسیدن به اشباع و جای بهترین دوره.','افزایش پایدار خطای اعتبارسنجی همراه کاهش آموزش می‌تواند نشانه بیش‌برازش باشد. نبود این الگو به تنهایی اثبات سلامت کامل یا نبود بیش‌برازش نیست. محور افقی دوره و محور عمودی خطا یا معیار مربوط است.')
    q('چرا خطای اعتبارسنجی از آموزش پایین‌تر است؟','آموزش با تبدیل‌های تصادفی و نمونه‌های ترکیبی دشوارتر انجام می‌شود و رفتار نرمال‌سازی نیز متفاوت است.','پس پایین‌تر بودن خطای اعتبارسنجی همیشه خطای محاسبه یا نشت داده نیست. مقایسه دو منحنی را باید با تفاوت پیش‌پردازش و شیوه محاسبه تفسیر کرد.')
    q('چرا محور تعداد رده‌ها لگاریتمی است؟','اختلاف تعداد رده‌ها زیاد است؛ مقیاس لگاریتمی اجازه می‌دهد رده‌های کم‌نمونه هم دیده شوند.','فاصله برابر روی محور لگاریتمی، نسبت برابر را نشان می‌دهد، نه اختلاف عددی برابر. قبل از ارائه، عنوان محور و پایه نمایش همان شکل را بخوان. هدف نمایش عدم توازن است، نه پنهان‌کردن آن.')
    q('run7 و run8 چقدر فرق داشتند؟','mAP@0.5 اعتبارسنجی از حدود ۰٫۸۴۶ به ۰٫۸۴۹ و آزمون از ۰٫۸۶۷ به ۰٫۸۷۴ رسید.','بهبود برای انتخاب پیکربندی همین پروژه مفید بوده؛ نتیجه را برتری عمومی قطعی AdamW ننام. مقایسه راهبرد شامل تغییر نرخ و زمان‌بند هم بوده است.')
    q('چرا با نتیجه YOLOv4 مقاله IADD مقایسه مستقیم نکردی؟','بخش آزمون مقاله و پروژه یکسان نیست؛ برچسب آزمون عمومی در دسترس نبود، داده و تقسیم متفاوت شد و کد و تنظیمات کامل آن آزمایش هم در اختیار نبود.','بنابراین دو عدد mAP بدون همسانی پروتکل، مقایسه کنترل‌شده ندارند. نتیجه مقاله می‌تواند زمینه معرفی باشد، نه اثبات میزان پیشرفت مدل ما.')
    q('آیا تصاویر دمو نماینده متوسط عملکردند؟','نمونه‌های منتخب برای نمایش انواع صحنه و تحلیل کیفی‌اند؛ معیار اصلی از کل بخش آزمون آمده است.','برخی نمونه‌ها بر اساس امتیاز و تعداد پیش‌بینی مناسب انتخاب شده‌اند. ادعای انتخاب تصادفی بی‌طرفانه همه دموها درست نیست. انتخاب تصویر نباید جای ارزیابی کامل را بگیرد.')
    q('کادر مرجع و کادر خروجی را چگونه رسم کردی؟','مرجع از فایل برچسب نسبی به مختصات پیکسلی تبدیل می‌شود؛ خروجی از boxes مدل و امتیازهای آن می‌آید.','چیدمان دو تصویر، پردازش نمایشی است و در ارزیابی مدل نقشی ندارد. کد رسم ساده و کد دمو در مدارک وجود دارند؛ می‌توان یک تصویر را جدا دوباره تولید کرد.')
    group('۹  محدودیت‌ها مستندسازی و سوال‌های پیگیری')
    q('آیا این مدل برای استفاده در خودروی واقعی آماده است؟','این پروژه آموزش و ارزیابی آفلاین آشکارساز است؛ برای کاربرد ایمنی واقعی، ارزیابی مستقل، سرعت، پایداری و شرایط بیشتری لازم است.','ادعای سامانه رانندگی خودکار کامل، کنترل خودرو یا تضمین ایمنی نکرده‌ایم. یک آشکارساز، بخشی از زنجیره ادراک است.')
    q('سرعت یا FPS مدل چقدر است؟','اگر آزمایش مستند روی سخت‌افزار مشخص نداریم، عدد عمومی سایت را به عنوان سرعت پروژه گزارش نمی‌کنم.','اندازه ۱۲۸۰، پردازنده، دسته، آماده‌سازی و NMS بر زمان اثر دارند. برای اندازه‌گیری باید گرم‌کردن، همگام‌سازی و تکرار مشخص داشته باشیم.')
    q('از کجا می‌فهمی نتیجه قابل بازتولید است؟','کد ساخت داده، شناسه بخش‌ها، تنظیمات، نسخه کتابخانه، وزن‌ها و خروجی معیارها ثبت شده‌اند.','seed و deterministic کمک می‌کنند، اما یکسانی قطعی عدد در همه نسخه‌ها و سخت‌افزارها را تضمین نمی‌کنند. بذر داده ۸۰ و بذر آموزش صفر دو تصمیم جدا هستند.')
    q('اگر داور یک عدد یا فرمول را خواست چه نشان بدهم؟','برای آمار داده، فایل شمارش و stats.json؛ برای آموزش args.yaml و results.csv؛ برای معماری وزن مدل و پیکربندی رسمی؛ برای معیار، متن فرمول و منبع آن در پایان‌نامه.','عدد پروژه را با استناد به مشاهده و کد خود پروژه توضیح بده. تعریف علمی را به منبع مربوط وصل کن. منبعی را که فرمول مشخصی در آن نیست به عنوان محل همان فرمول معرفی نکن.')
    q('کمک هوش مصنوعی چه جایگاهی در کار داشته است؟','باید سهم ابزار را مطابق واقع توضیح داد؛ مثلا کمک در تدوین، ترسیم یا بررسی کد، همراه با مسئولیت فهم و اعتبارسنجی خروجی.','نسخه ساده کد، مدرک نویسندگی مستقل گذشته نیست. پاسخ قابل دفاع این است که مسیر محاسبه را فهمیده‌ام، خروجی را بررسی کرده‌ام و می‌توانم آن را بازتولید و توضیح بدهم؛ ادعای خلاف واقع درباره منشأ فایل‌ها نکن.')
    q('اگر جواب سوالی را ندانستم چه کنم؟','معنای سوال را دقیق کن، چیزی را که می‌دانی توضیح بده و بخش نیازمند بررسی را مشخص بگو.','مثلا بگو «عدد دقیق را از خلاصه مدل می‌خوانم؛ تفاوت مراحل اصلی و لایه‌های داخلی این است». حدس قطعی یا حفظ‌کردن یک عدد بدون تعریف، پاسخ را شکننده می‌کند.')
    q('اولین پیشنهاد بهبود بعدی چیست؟','پس از تثبیت ارزیابی، بررسی هدفمند کیفیت برچسب و خطاهای اشیای کوچک؛ سپس آزمایش مستقل تغییرهای مدل و تنظیمات.','اثر چند عامل را جدا، با تکرار و روی تقسیم ثابت بسنجیم. افزایش وضوح از تصویر خام و ارزیابی داده مستقل نیز مسیرهای بعدی‌اند؛ لازم نیست همه آن‌ها در دامنه پروژه کارشناسی انجام شده باشند.')
    starts={i:name for name,i in groups}
    for i,(question,short,detail,source) in enumerate(QUESTIONS):
        if i in starts:h(d,starts[i])
        h(d,f'{str(i+1).translate(str.maketrans("0123456789","۰۱۲۳۴۵۶۷۸۹"))}  {question}',2)
        p(d,'پاسخ کوتاه: '+short)
        if detail:p(d,'اگر سوال ادامه یافت: '+detail)
        if source:p(d,'محل بررسی: '+source)
    h(d,'برگه تمرین با داده واقعی')
    table(d,['رده','AP در هم‌پوشانی ۰٫۵','AP در بازه ۰٫۵ تا ۰٫۹۵'],[
        ['شخص','۰٫۸۶۸','۰٫۶۶۴'],['خودروی سبک','۰٫۹۶۹','۰٫۸۴۹'],['موتورسیکلت','۰٫۹۲۸','۰٫۶۳۱'],['اتوبوس','۰٫۷۹۸','۰٫۶۹۷'],['خودروی باری','۰٫۸۶۷','۰٫۷۸۴'],['چراغ راهنمایی','۰٫۸۱۳','۰٫۶۱۸']],[5,6,6])
    p(d,'تمرین: یک دقیقه تفاوت اتوبوس و موتورسیکلت را از نظر یافتن شیء و دقت مکان‌یابی توضیح بده. سپس بگو از این عددها چه چیزی را نمی‌توان قطعی نتیجه گرفت. در مرور بعد، مسیر یک کادر از برچسب نسبی تا مختصات ورودی و خروجی را روی کاغذ حل کن.')
    sources(d)
    path=OUT/'۰۲_پرسش‌وپاسخ_جامع_دفاع.docx';d.save(path);return path

